#include <vector>
#include <stdexcept>

std::vector<unsigned char> pad_data(const std::vector<unsigned char>& data) {
    size_t data_len = data.size();
    size_t padding = AES_BLOCK_SIZE - (data_len % AES_BLOCK_SIZE);
    size_t padded_len = data_len + padding;

    std::vector<unsigned char> padded_data(data.begin(), data.end());
    padded_data.resize(padded_len, (unsigned char)padding);

    return padded_data;
}

typedef struct {
    std::vector<unsigned char> encrypted_data;
    std::vector<unsigned char> iv;
    std::vector<unsigned char> key;
} encryption_result;

encryption_result encrypt_data(
    const std::vector<unsigned char>& key,
    const std::vector<unsigned char>& data
) {
    if (key.size() < 32) {
        throw std::invalid_argument("Key must be at least 32 bytes long");
    }

    try {
        unsigned char iv[AES_BLOCK_SIZE];
        if (RAND_bytes(iv, AES_BLOCK_SIZE) != 1) {
            throw std::runtime_error("Failed to generate IV");
        }

        std::vector<unsigned char> aes_key(key.begin(), key.begin() + 32);

        AES_KEY aes_enc_key;
        if (AES_set_encrypt_key(aes_key.data(), 256, &aes_enc_key) != 0) {
            throw std::runtime_error("Failed to set encryption key");
        }

        std::vector<unsigned char> padded_data = pad_data(data);

        int encrypted_len = padded_data.size();
        std::vector<unsigned char> encrypted_data(encrypted_len);
        std::vector<unsigned char> tag(AES_GCM_TAG_LEN);

        if (AES_gcm_encrypt(&aes_enc_key, iv, AES_BLOCK_SIZE,
                           nullptr, 0,
                           padded_data.data(), encrypted_data.data(),
                           encrypted_len, tag.data())) {
            throw std::runtime_error("Failed to encrypt data");
        }

        encrypted_data.insert(encrypted_data.end(), tag.begin(), tag.end());

        encryption_result result;
        result.encrypted_data = encrypted_data;
        result.iv.assign(iv, iv + AES_BLOCK_SIZE);
        result.key = aes_key;

        OPENSSL_cleanse(&aes_enc_key, sizeof(aes_enc_key));
        OPENSSL_cleanse(iv, AES_BLOCK_SIZE);

        return result;

    } catch (const std::exception& e) {
        OPENSSL_cleanse(key.data(), key.size());
        throw;
    }
}
